package com.healthcoach.app
import android.content.Context;import androidx.work.*
class HealthSyncWorker(c:Context,p:WorkerParameters):CoroutineWorker(c,p){override suspend fun doWork():Result{val pref=AppPrefs(applicationContext);val folder=pref.folderUri?:return Result.failure();return try{val r=HealthReader(applicationContext);if(!r.allowed()){pref.lastError="Autorisations Santé Connect manquantes";return Result.failure()};val s=r.snapshot();HealthExporter.write(applicationContext,folder,"healthcoach_current.json",HealthExporter.current(s));HealthExporter.write(applicationContext,folder,"healthcoach_status.json",HealthExporter.status(s));HealthExporter.write(applicationContext,folder,"healthcoach_history.json",HealthExporter.history(s));pref.lastSync=System.currentTimeMillis();pref.lastError=null;Result.success()}catch(e:Exception){pref.lastError=e.message;Result.retry()}}}